func detectCredentialedURIs(s string) []taggedRegion {
	var regions []taggedRegion
	for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
		start, end := loc[0], trimCredentialedURIEnd(s, loc[0], loc[1])
		if start >= end {
			continue
		}
		if hasURIUserPassword(s[start:end]) {
			regions = append(regions, taggedRegion{region: region{start, end}})
		}
	}
	return regions
}

func trimCredentialedURIEnd(s string, start, end int) int {
	for end > start {
		switch s[end-1] {
		case '.', ',', ';', ':', '!', '?', ')', ']', '}':
			end--
		default:
			return end
		}
	}
	return end
}

func hasURIUserPassword(candidate string) bool {
	u, err := url.Parse(candidate)
	if err != nil || u.Scheme == "" || u.Host == "" || u.User == nil {
		return false
	}
	password, ok := u.User.Password()
	return ok && password != ""
}

