package redact

import (
	"net/url"
	"regexp"
	"strings"
)

var (
	jdbcPattern               = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
	databaseURLPattern        = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
	postgresKeywordPattern    = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
	semicolonConnPattern      = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|[^=;"'\s]+)){2,}`)
	credentialValuePattern    = regexp.MustCompile(`(?i)\b((?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)[_-]?(?:password|passwd|pwd)|pgpassword|mysql_pwd|redis_password|mongo_password|mongodb_password)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
	passwordAssignmentPattern = regexp.MustCompile(`(?i)(?:[?&;]|^)password=([^&;\s"']+)`)
)

func detectConnectionStrings(s string) []taggedRegion {
	var regions []taggedRegion
	regions = append(regions, detectJDBCConnectionStrings(s)...)
	regions = append(regions, detectDatabaseURLsWithPasswordQuery(s)...)
	regions = append(regions, detectPostgresKeywordDSNs(s)...)
	regions = append(regions, detectSemicolonConnectionStrings(s)...)
	return regions
}

func detectCredentialValues(s string) []taggedRegion {
	var regions []taggedRegion
	for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
		if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
			continue
		}
		start, end := loc[4], loc[5]
		value := s[start:end]
		if len(value) >= 2 {
			first, last := value[0], value[len(value)-1]
			if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
				start++
				end--
				value = s[start:end]
			}
		}
		if hasNonPlaceholderPasswordValue(value) {
			regions = append(regions, taggedRegion{region: region{start, end}})
		}
	}
	return regions
}

func detectJDBCConnectionStrings(s string) []taggedRegion {
	return detectPatternConnectionStrings(s, jdbcPattern, hasJDBCPassword)
}

func hasJDBCPassword(candidate string) bool {
	withoutPrefix, ok := strings.CutPrefix(strings.ToLower(candidate), "jdbc:")
	if !ok {
		return false
	}
	if hasParsedURIUserPassword(withoutPrefix) {
		return true
	}
	return hasNonPlaceholderPasswordAssignment(candidate)
}

func detectDatabaseURLsWithPasswordQuery(s string) []taggedRegion {
	return detectPatternConnectionStrings(s, databaseURLPattern, hasDatabaseURLPasswordQuery)
}

func detectPatternConnectionStrings(
	s string,
	pattern *regexp.Regexp,
	hasSecret func(string) bool,
) []taggedRegion {
	var regions []taggedRegion
	for _, loc := range pattern.FindAllStringIndex(s, -1) {
		start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
		if start >= end {
			continue
		}
		candidate := s[start:end]
		if hasSecret(candidate) {
			regions = append(regions, taggedRegion{region: region{start, end}})
		}
	}
	return regions
}

func trimConnectionStringEnd(s string, start, end int) int {
	for end > start {
		switch s[end-1] {
		case '.', ',', ';', ':', '!', '?', ')', ']':
			end--
		default:
			return end
		}
	}
	return end
}

func hasDatabaseURLPasswordQuery(candidate string) bool {
	u, err := url.Parse(candidate)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return false
	}
	return hasNonPlaceholderPasswordValue(u.Query().Get("password"))
}

func detectPostgresKeywordDSNs(s string) []taggedRegion {
	return detectKeyValueConnectionStrings(
		s,
		postgresKeywordPattern,
		parseSpaceSeparatedKeyValues,
		hasRequiredPostgresDSNKeys,
	)
}

func parseSpaceSeparatedKeyValues(candidate string) map[string]string {
	values := make(map[string]string)
	for _, field := range strings.Fields(candidate) {
		key, value, ok := strings.Cut(field, "=")
		if !ok {
			continue
		}
		values[strings.ToLower(key)] = strings.Trim(value, `"'`)
	}
	return values
}

func hasRequiredPostgresDSNKeys(values map[string]string) bool {
	password, hasPassword := values["password"]
	_, hasHost := values["host"]
	_, hasUser := values["user"]
	return hasHost && hasUser && hasPassword && hasNonPlaceholderPasswordValue(password)
}

func detectSemicolonConnectionStrings(s string) []taggedRegion {
	return detectKeyValueConnectionStrings(
		s,
		semicolonConnPattern,
		parseSemicolonKeyValues,
		hasRequiredSemicolonConnectionKeys,
	)
}

func detectKeyValueConnectionStrings(
	s string,
	pattern *regexp.Regexp,
	parse func(string) map[string]string,
	hasRequiredKeys func(map[string]string) bool,
) []taggedRegion {
	var regions []taggedRegion
	for _, loc := range pattern.FindAllStringIndex(s, -1) {
		candidate := s[loc[0]:loc[1]]
		values := parse(candidate)
		if hasRequiredKeys(values) {
			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
		}
	}
	return regions
}

func parseSemicolonKeyValues(candidate string) map[string]string {
	values := make(map[string]string)
	for _, part := range strings.Split(candidate, ";") {
		key, value, ok := strings.Cut(part, "=")
		if !ok {
			continue
		}
		values[normalizeConnectionKey(key)] = strings.Trim(value, `"'`)
	}
	return values
}

func normalizeConnectionKey(key string) string {
	key = strings.ToLower(strings.TrimSpace(key))
	key = strings.ReplaceAll(key, " ", "")
	key = strings.ReplaceAll(key, "_", "")
	key = strings.ReplaceAll(key, "-", "")
	return key
}

func hasRequiredSemicolonConnectionKeys(values map[string]string) bool {
	hasServer := hasAnyKey(values, "server", "datasource", "address", "addr", "networkaddress")
	hasUser := hasAnyKey(values, "user", "userid", "uid")
	password, hasPassword := firstValueForKey(values, "password", "pwd")
	return hasServer && hasUser && hasPassword && hasNonPlaceholderPasswordValue(password)
}

func hasAnyKey(values map[string]string, keys ...string) bool {
	for _, key := range keys {
		if _, ok := values[key]; ok {
			return true
		}
	}
	return false
}

func firstValueForKey(values map[string]string, keys ...string) (string, bool) {
	for _, key := range keys {
		value, ok := values[key]
		if ok {
			return value, true
		}
	}
	return "", false
}

func hasParsedURIUserPassword(candidate string) bool {
	u, err := url.Parse(candidate)
	if err != nil || u.Scheme == "" || u.Host == "" || u.User == nil {
		return false
	}
	password, ok := u.User.Password()
	return ok && hasNonPlaceholderPasswordValue(password)
}

func hasNonPlaceholderPasswordAssignment(candidate string) bool {
	for _, match := range passwordAssignmentPattern.FindAllStringSubmatch(candidate, -1) {
		if len(match) > 1 && hasNonPlaceholderPasswordValue(match[1]) {
			return true
		}
	}
	return false
}

func hasNonPlaceholderPasswordValue(value string) bool {
	return value != "" && !isPlaceholderSecretValue(value)
}

